  and owner_principal = #{owner}
  and request_key = #{requestKey}

select id, form_id, row_json, success, error_msg, create_by, create_time, owner_principal, request_key, payload_hash, submission_status, review_by, review_note, review_time from bi_data_form_record where form_id = #{formId}
